    nexacro._resolveTypeByPath = function (ctxt, path) 
    {
        if (!path) 
        {
            return undefined;
        }

        const keys = path.replace(/\[["']?([^"'\]]+)["']?\]/g, '.$1').split('.');
        if (keys[0] === "nexacro") 
        {
            ctxt = nexacro;
            keys.shift();
        }
        else if (keys[0] === "this") 
        {
            keys.shift();
        }
        if (ctxt === null)
        {
            ctxt = (typeof globalThis !== "undefined") ? globalThis : window;
        }
        
        return keys.reduce(function(cur, key) {
            if (cur == null) 
            {
                return undefined; 
            }
            return cur[key];
        }, ctxt);
    };

    nexacro._parseJsonLiteral = function (str)
    {
        let obj = null;
        if (str == null || str.length === 0)
        {
            return null;
        }

        if (typeof str === "object")
        {
            return str;
        }

        try 
        {
            obj = JSON.parse(str);
        }
        catch (_e)
        {
            obj = nexacro._createExprFunc(`(${str})`)?.call(null);
        }
        return obj;
    };  


