    nexacro._setRootCSSVariable = function (nodeStyle, varname, value)
    {
        nodeStyle.setProperty(`--${varname}`, value);
    };

    nexacro._updateRootCSSVariable = function (nodeStyle, id, type, value)
    {
        const _setCSSVariableHandler = {
            wordwrap: (style, nodeid, nodevalue) => 
            {
                // wordwrap : white-space, word-break, word-wrap
                if (nodevalue == "char")
                {
                    nexacro._setRootCSSVariable(style, "white-space-" + nodeid, "pre-wrap");
                    nexacro._setRootCSSVariable(style, "word-break-" + nodeid, "break-all");
                    nexacro._setRootCSSVariable(style, "word-wrap-" + nodeid, "break-word");
                }
                else if (nodevalue == "english")
                {
                    nexacro._setRootCSSVariable(style, "white-space-" + nodeid, "pre-wrap");
                    nexacro._setRootCSSVariable(style, "word-break-" + nodeid, "normal");
                    nexacro._setRootCSSVariable(style, "word-wrap-" + nodeid, "break-word");
                }
                else // none
                {
                    nexacro._setRootCSSVariable(style, "white-space-" + nodeid, "pre");
                    nexacro._setRootCSSVariable(style, "word-break-" + nodeid, "normal");
                    nexacro._setRootCSSVariable(style, "word-wrap-" + nodeid, "normal");
                }
            },
            edge: (style, nodeid, nodevalue) =>
            {
                // edge : border-image
                const arr = nodevalue.split(' ');
                if (arr.length > 1)
                {
                    const image = arr[0];
                    const fixedwidth = arr.length > 1 ? arr[1] : "0px";
                    const fixedheight = arr.length > 2 ? arr[2] : "0px";

                    nodevalue = `${image} ${fixedwidth.replace('px', '')} ${fixedheight.replace('px', '')} fill / ${fixedwidth} ${fixedheight}`;
                }
                else // none
                {
                    nodevalue = "none 100% / 0px";
                }
                nexacro._setRootCSSVariable(style, "border-image-" + nodeid, nodevalue);
            }
        };

        const _setCSSVariable = (style, nodeid, nodetype, nodevalue) =>
        {
            const handler = _setCSSVariableHandler[nodetype];
            if (handler)
            {
                handler(style, nodeid, nodevalue);
            }
        };

        _setCSSVariable(nodeStyle, id, type, value);
    };

    nexacro._CommunicationItem = function (path, type, bcache, last_modified, version, env)
    {
        this.path = path;
        this.handle = null;
        this.callbackList = [];
        this.type = type;
        this.bcache = bcache;
        this.last_modified = last_modified;
        this.version = version ? version : "0";

        var ar = path.split("://");
        if (ar)
        {
            this.protocol = ar[0];
            switch (this.protocol)
            {
                case "http": this._protocol = 0; break;
                case "https": this._protocol = 1; break;
                case "file": this._protocol = 2; break;
                default: this._protocol = -1; break;
            }
        }

        this._env = env;
        this._addCookieFromCookieVariables();

        //== internal value ==//
        this._check_responseXML = false; // do not read responseXML.
    };
    var __pCommunicationItem = nexacro._CommunicationItem.prototype;

    __pCommunicationItem.appendCallback = function (pthis, callbackFn)
    {
        var callbackList = this.callbackList;
        callbackList.push({ target: pthis, callback: callbackFn });
    };

    __pCommunicationItem.removeCallback = function (pthis, callbackFn)
    {
        var callbackList = this.callbackList;
        var n = callbackList.length;
        if (n > 0)
        {
            for (var i = 0; i < n; i++)
            {
                var item = callbackList[i];
                if (item.pthis == pthis && item.callback == callbackFn)
                {
                    callbackList.splice(i, 1);
                    if (callbackList.length === 0)
                    {
                        if (this.handle)
                            nexacro.__cancelCommunication(this.handle);
                        this.handle = null;
                        delete nexacro._CommunicationManager[this.path];
                    }
                    return true;
                }
            }
        }
        return false;
    };

    __pCommunicationItem._addCookieFromCookieVariables = function ()
    {
        this._env?._addCookieFromCookieVariables();
    };

    __pCommunicationItem._addCookieFromEnvHeadVariables = function (/*headers*/)
    {
        //var env = nexacro.getEnvironment();
        //Head Variable Cookie을 추가
        //TODO
        /*
        var len = headers.length;
        for (var i = 0; i < len; i++)
        {
            nexacro._setCookie(headers[i].id, headers[i].value);
        }*/
    };

    __pCommunicationItem._addCookieToCookieVariable = function (cookieStr)
    {
        this._env?._addCookieToCookieVariable(cookieStr);
    };

    __pCommunicationItem.on_decrypt = function (data)
    {
        if (this._protocol < 0)
        {
            var protocoladp =  this.env?._getProtocol(this.protocol);
            if (protocoladp)
            {
                data = protocoladp.decrypt(this.path, data);
            }
        }
        return data;
    };

    __pCommunicationItem.on_encrypt = function (data)
    {
        if (this._protocol < 0)
        {
            var protocoladp = this.env?._getProtocol(this.protocol);
            if (protocoladp)
            {
                data = protocoladp.encrypt(this.path, data);
            }
        }
        return data;

    };

    __pCommunicationItem._getEnvironment = function ()
    {
        return this._env;
    };

    __pCommunicationItem.on_start = nexacro._emptyFn;
    __pCommunicationItem.on_load = nexacro._emptyFn;

    __pCommunicationItem._getCacheList = function (path)
    {
        if (this._env)
        {
            return this._env._getModuleCacheList(path);
        }
        return nexacro._CacheList[path];
    };

    __pCommunicationItem._addCacheList = function (path, data)
    {
        if (this._env)
        {
            return this._env._addModuleCacheList(path, data);
        }
        return nexacro._CacheList[path] = data;
    };

    __pCommunicationItem.on_load_module = function (data, cookie, last_modified)
    {
        // first, remove item from Manager
        // because, the new item can append at callback function.
        delete nexacro._CommunicationManager[this.path];
        var module;
        if (typeof (data) == "function")
        {
            module = data;
            module.bcache = this.bcache;

            this._addCookieToCookieVariable(cookie);

            if (this.bcache)
            {
                var m_cache = this._getCacheList(this.path);
                if (!m_cache)
                {
                    this._addCacheList(this.path, { data: module, last_modified: last_modified || "", version: this.version });
                }
                else
                {
                    m_cache.data = module;
                    if (last_modified)
                        m_cache.last_modified = last_modified;
                    m_cache.version = this.version;
                }
            }
        }
        else if (typeof (data) == "undefined" && this.bcache)
        {            
            var cache = this._getCacheList(this.path);
            module = cache.data;
        }
        else
        {
            if (this._protocol < 0)
            {
                data = this.on_decrypt(data);
            }

            this._addCookieToCookieVariable(cookie);

            // stringrc 처리가 json으로 변경. dead code
            //if (this.path && this.path.indexOf("_resource_/_stringrc_/") > -1)
            //    module = nexacro._executeEvalStr(data, this.path);
            //else
            module = nexacro._executeGlobalEvalStr(data, this.path);

            if (module)
                module.bcache = this.bcache;

            if (this.bcache)
            {
                var m_cache = this._getCacheList(this.path);

                if (!m_cache)
                {
                    this._addCacheList(this.path, { data: module, last_modified: last_modified, version: this.version });
                }
                else
                {
                    m_cache.data = module;
                    m_cache.last_modified = last_modified;
                    m_cache.version = this.version;
                }
            }
        }

        var callbackList = this.callbackList;
        var item = null;

        if (callbackList.length > 0)
        {
            while (item = callbackList.pop())
            {
                var target = item.target;
                const env = target.context._getEnvironment();
                if (env)
                    nexacro._pushCurrentEnvironment(env);
                if (target && target.context && target.context.on_fire_oninit)
                {
                    target.context.on_fire_oninit(target.context);
                }

                item.callback.call(target, this.path, 0, module);
                if (env)
                    nexacro._popCurrentEnvironment();
            }            
        }

        this.handle = null;
    };

    __pCommunicationItem.on_load_text = function (data, cookie, last_modified)
    {
        delete nexacro._CommunicationManager[this.path];

        if (this._protocol < 0)
            data = this.on_decrypt(data);

        this._addCookieToCookieVariable(cookie);

        if (this.bcache)
        {
            var m_cache = this._getCacheList(this.path);
            if (!m_cache)
            {
                this._addCacheList(this.path, { data: data, last_modified: last_modified, version: this.version });
            }
            else
            {
                m_cache.data = data;
                m_cache.last_modified = last_modified;
                m_cache.version = this.version;
            }
        }

        var callbackList = this.callbackList;
        var n = callbackList.length;
        if (n > 0)
        {   
            for (var i = 0; i < n; i++)
            {
                var item = callbackList[i];
                var target = item.target;
                if (target._is_alive !== false)
                {
                    const env = target.context._getEnvironment();
                    if (env)
                        nexacro._pushCurrentEnvironment(env);
                    item.callback.call(target, this.path, 0, data);
                    if (env)
                        nexacro._popCurrentEnvironment();
                }
            }
            callbackList.splice(0, n);
        }
        this.handle = null;
    };
