        {
            var arrArguments =
                [
                    undefined,
                    0 // Sync Call
                ];
            arrArguments.push("__getLastErrorMessageExtensionAPI");
            return nexacro._callExtensionLibraryMethod.apply(this, arrArguments);
        }
        else
            return nexacro.__getLastErrorMessageExtensionAPI();
