    nexacro._DEVICE = "";       // Web/Desktop Runtime : "", Mobile App(Android Runtime, Hybrid) : mobideproducttype
    nexacro._SystemType = "";   // win32(Win64 없음), ipad, iphone, android, winphone, mac, linux
