            var v = node_style.backgroundPosition + "";
            var halign = "left";    //default
            var valign = "";
            if (v.length > 0)
            {
                var align = v.split(/\s+/);
                valign = align[1] ? align[1] : "";
            }

            if (!valign)
                node_style.backgroundPosition = "";
            else
                node_style.backgroundPosition = halign + " " + valign;
