    nexacro.__getHTMLStyle_LayoutGap = function (layouthorizontalgap, layoutverticalgap)
    {
        var _toGapValue = function (v)
        {
            if (v === undefined || v === null || v === "")
                return "";

            if (typeof v == "number")
                return v + "px";

            var str = nexacro._toString(v).trim();
            if (!str)
                return "";

            return (/^[-+]?\d*\.?\d+$/.test(str)) ? (str + "px") : str;
        };

        var hgap = _toGapValue(layouthorizontalgap);
        var vgap = _toGapValue(layoutverticalgap);

        if (hgap && vgap)
            return "gap:" + vgap + " " + hgap + ";";
        if (hgap)
            return "gap:0px " + hgap + ";";
        if (vgap)
            return "gap:" + vgap + " 0px;";
        return "";
    };

    nexacro.__setDOMStyle_LayoutGap = function (node_style, layouthorizontalgap, layoutverticalgap)
    {
        var _toGapValue = function (v)
        {
            if (v === undefined || v === null || v === "")
                return "";

            if (typeof v == "number")
                return v + "px";

            var str = nexacro._toString(v).trim();
            if (!str)
                return "";

            return (/^[-+]?\d*\.?\d+$/.test(str)) ? (str + "px") : str;
        };

        var hgap = _toGapValue(layouthorizontalgap);
        var vgap = _toGapValue(layoutverticalgap);

        if (hgap && vgap)
            node_style.gap = vgap + " " + hgap;
        else if (hgap)
            node_style.gap = "0px " + hgap;
        else if (vgap)
            node_style.gap = vgap + " 0px";
        else
            node_style.gap = "";
    };

