    nexacro.__setDOMStyle_LayoutSpacing = function (node_style, layoutspacing)
    {
        var _toPaddingValue = function (v)
        {
            if (v === undefined || v === null || v === "")
                return "";

            if (typeof v == "number")
                return v + "px";

            var str = nexacro._toString(v).trim();
            if (!str)
                return "";

            return (/^[-+]?\d*\.?\d+$/.test(str)) ? (str + "px") : str;
        };

        if (nexacro._isObject(layoutspacing))
        {
            if (layoutspacing.value && /(\d*\.?\d+)(em|rem)\b/i.test(layoutspacing.value))
            {
                node_style.padding = layoutspacing.value;
                node_style.paddingInline = "";
                node_style.paddingBlock = "";
            }
            else
            {
                node_style.padding = "";
                node_style.paddingInline = _toPaddingValue(layoutspacing.left) + " " + _toPaddingValue(layoutspacing.right);
                node_style.paddingBlock = _toPaddingValue(layoutspacing.top) + " " + _toPaddingValue(layoutspacing.bottom);
            }
        }
        else if (layoutspacing !== undefined && layoutspacing !== null && layoutspacing !== "")
        {
            var spacing = _toPaddingValue(layoutspacing);
            if (/(\d*\.?\d+)(em|rem)\b/i.test(spacing) || /\s/.test(spacing))
            {
                node_style.padding = spacing;
                node_style.paddingInline = "";
                node_style.paddingBlock = "";
            }
            else
            {
                node_style.padding = "";
                node_style.paddingInline = spacing + " " + spacing;
                node_style.paddingBlock = spacing + " " + spacing;
            }
        }
        else
        {
            node_style.padding = "";
            node_style.paddingInline = "";
            node_style.paddingBlock = "";
        }
    };

    nexacro.__getHTMLStyle_LayoutSpacing = function (layoutspacing)
    {
        var _toPaddingValue = function (v)
        {
            if (v === undefined || v === null || v === "")
                return "";

            if (typeof v == "number")
                return v + "px";

            var str = nexacro._toString(v).trim();
            if (!str)
                return "";

            return (/^[-+]?\d*\.?\d+$/.test(str)) ? (str + "px") : str;
        };

        if (nexacro._isObject(layoutspacing))
        {
            if (layoutspacing.value && /(\d*\.?\d+)(em|rem)\b/i.test(layoutspacing.value))
                return "padding:" + layoutspacing.value + ";";

            return "padding-inline:" + _toPaddingValue(layoutspacing.left) + " " + _toPaddingValue(layoutspacing.right) + ";" +
                    "padding-block:" + _toPaddingValue(layoutspacing.top) + " " + _toPaddingValue(layoutspacing.bottom) + ";";
        }

        if (layoutspacing !== undefined && layoutspacing !== null && layoutspacing !== "")
        {
            var spacing = _toPaddingValue(layoutspacing);
            if (/(\d*\.?\d+)(em|rem)\b/i.test(spacing) || /\s/.test(spacing))
                return "padding:" + spacing + ";";

            return "padding-inline:" + spacing + " " + spacing + ";" +
                    "padding-block:" + spacing + " " + spacing + ";";
        }
        if (layoutspacing)
        {
            return "padding-inline:" + layoutspacing + "px" + " " + layoutspacing + "px" + ";" + "padding-block:" + layoutspacing + "px" + " " + layoutspacing + "px" + ";";
        }
        return "";
    };

    nexacro.__clearDOMStyle_LayoutSpacing = function (node_style)
    {
        node_style.padding = "";
    };

