    {
        var url;
        var ln = arguments.length;
        switch (ln)
        {
            case 1:
                url = canvas._draw_node.toDataURL();
                break;
            case 2:
                url = canvas._draw_node.toDataURL(imgType);
                break;
            case 3:
                url = canvas._draw_node.toDataURL(imgType, ImgOption);
                break;
        }
        if (url)
        {
            var imgObj = new nexacro.Image();
            imgObj.set_src(url);
            return imgObj;
        }
    };
