    nexacro._showModalSync = nexacro._emptyFn;
    nexacro._showModalWindow = nexacro._emptyFn;
    if (globalThis.chrome && globalThis.chrome.webview)
    {
        nexacro._showModalSync = async function (childframe, str_id, _parent_frame, arr_arg, opener)
        {
            if (childframe !== null)
                return await childframe.showModal(str_id, _parent_frame, arr_arg, opener, null, false);

            throw nexacro.MakeReferenceError(this, "reference_not_define", str_id);
        };

        nexacro._showModalWindow = async function (childframe, str_id, parent_frame, arr_arg, opener)
        {
            if (childframe !== null)
                return await childframe._showModalWindow(str_id, parent_frame, arr_arg, opener);

            throw nexacro.MakeReferenceError(this, "reference_not_define", str_id);
        };
    }

    //==============================================================================
    // Script Load Utils
    //==============================================================================
    // __createHttpRequest (html only)
    nexacro.__createHttpRequest = function (win_handle)
    {
        var _ajax = {};
        //_ajax._destroy = nexacro._emptyFn;
        _ajax._destroy = function ()
        {
            if (this.handle)
            {
                if (this._reader)
                {
                    delete this._reader;
                    this._reader = null;
                }

                delete this.handle.responseText;
                delete this.handle['onreadystatechange'];
                this.handle.onreadystatechange = null;
                delete this.handle;
                this.handle = null;
            }
        };

        if (win_handle)
            _ajax.handle = new win_handle.XMLHttpRequest();
        else
            _ajax.handle = new XMLHttpRequest();

        return _ajax;
    };

    nexacro.__createFakeHttpRequest = function (ndatatype, compress, async, reqtype)
    {
        var _ajax = {};
        _ajax._destroy = function () { if (this.handle) this.handle.destory(); };
        _ajax.handle = new nexacro.FakeXMLHttpRequest("FakeXMLHttpRequest", this, ndatatype, compress, async, reqtype);
        return _ajax;
    };

    nexacro.__checkAjaxSuccess = function (ajax)
    {
        var ajax_handle = ajax.handle;
        if (ajax_handle.readyState == 4)
        {
            var statusNum = ajax_handle.status || 200;
            return (statusNum >= 200 && statusNum < 300) ? statusNum : -statusNum;
        }
        //ajax_handle = null;
        return 0;
    };
    nexacro.__checkAjaxStatus = function (ajax)
    {
        var ajax_handle = ajax.handle;
        var ajaxstatus = ajax_handle.readyState;
        if (ajaxstatus == 4)
        {
            // File Protocol일땐 안타도록.
            if (ajax._protocol != 2)
            {
                //chrome, ff
                if (ajax_handle.status === 0 && ajax_handle.statusText === "")
                {
                    return 0;
                }
            }

            var statusNum = ajax_handle.status || 200;
            //ajax_handle = null;
            return (statusNum >= 200 && statusNum < 300) ? statusNum : -statusNum;
        }
        else
        {
            //ajax_handle = null;
            return ajaxstatus === 0 ? 1 : ajaxstatus;
        }
    };

    nexacro._loadScriptTag = function (loadItem, url, last_modified)
    {
        const script = document.createElement('script');
        script.src = url;

        const env = nexacro.getEnvironment();
        if (env && env.networksecurelevel == "all")
            script.crossOrigin = "use-credentials";

        script.addEventListener("loadModule", (evt) => {
            const cookie = loadItem.context && loadItem.context._is_component
                ? loadItem.context._getWindow()._doc.cookie
                : document.cookie;
            loadItem.on_load_module(evt.detail, cookie, last_modified);
            script.remove();
        }, { once: true });

        script.addEventListener("error", () => {
            loadItem.on_error && loadItem.on_error();
            delete nexacro._CommunicationManager[loadItem.path];
            script.remove();
        }, { once: true });

        document.head.appendChild(script);
        return script;
    };

    nexacro.__startScriptTagLoad = function (loadItem, url, cachelevel)
    {
        var sep = url.indexOf("?") > -1 ? "&" : "?";

        if (cachelevel == "none")
        {
            return nexacro._loadScriptTag(loadItem, url + sep + "_t=" + Date.now(), null);
        }
        else if (cachelevel == "dynamic")
        {
            fetch(url, { method: "HEAD", cache: "no-cache" })
                .then((response) => {
                    const serverLastModified = response.headers.get("Last-Modified");
                    const cacheData = loadItem._getCacheList(loadItem.path);

                    if (cacheData && serverLastModified && serverLastModified === loadItem.last_modified)
                    {
                        const cookie = loadItem.context && loadItem.context._is_component
                            ? loadItem.context._getWindow()._doc.cookie
                            : document.cookie;
                        loadItem.on_load_module(cacheData.data, cookie, serverLastModified);
                    }
                    else
                    {
                        const scriptUrl = serverLastModified
                            ? url + sep + "_lm=" + encodeURIComponent(serverLastModified)
                            : url + sep + "_t=" + Date.now();
                        nexacro._loadScriptTag(loadItem, scriptUrl, serverLastModified);
                    }
                })
                .catch(() => {
                    nexacro._loadScriptTag(loadItem, url + sep + "_t=" + Date.now(), null);
                });
            return null;
        }
        else
        {
            return nexacro._loadScriptTag(loadItem, url, null);
        }
    };

    nexacro.__bindLoadModuleHandler = function (_ajax, pthis)
    {
        return function (e)
        {
            if (!_ajax || !_ajax.handle) return;
            var ajax_handle = _ajax.handle;
            var is_abort = _ajax.aborted;
            var status = (is_abort ? -1 : nexacro.__checkAjaxStatus(_ajax));
            var cookie = "";
            if (status > 0)
            {
                if (status >= 4)
                {
                    if (pthis.context)
                    {
                        if (pthis.context._is_component)
                            cookie = pthis.context._getWindow()._doc.cookie;
                        else
                            cookie = document ? document.cookie : null;
                    }
                    var data;
                    if (ajax_handle.responseType == "arraybuffer")
                    {
                        const inbuf = ajax_handle.response;
                        let arr = nexacro._decodeBuffer(inbuf)
                        if (arr)
                        {
                            data = arr;
                        }
                        else
                        {
                            arr = new Uint8Array(inbuf);
                            let encoding = "utf-8";
                            if (arr[0] == 0xEF && arr[1] == 0xBB && arr[2] == 0xBF)
                            {
                                encoding = "utf-8";
                            }
                            else if (arr[0] == 0xFE && arr[1] == 0xFF)
                            {
                                encoding = "utf-16be";
                            }
                            else if (arr[0] == 0xFF && arr[1] == 0xFE)
                            {
                                encoding = "utf-16le";
                            }
                            let decoder = new TextDecoder(encoding);
                            data = decoder.decode(arr);
                        }
                    }
                    else
                    {
                        data = ajax_handle.responseText;
                    }

                    var last_modified = ajax_handle.getResponseHeader("Last-Modified");

                    pthis.on_load_module(data, cookie, last_modified);
                    _ajax._destroy();
                    _ajax = null;
                    pthis = null;
                }
            }
            else
            {
                if (status == -304)     //Not Modified
                {
                    if (pthis.context)
                    {
                        if (pthis.context._is_component)
                            cookie = pthis.context._getWindow()._doc.cookie;
                        else
                            cookie = document ? document.cookie : null;
                    }

                    pthis.bcache = false;
                    const env = pthis.context._getEnvironment();
                    var m_cache = env._getModuleCacheList(pthis.path);
                    pthis.on_load_module(m_cache.data, cookie, m_cache.last_modified);
                    _ajax._destroy();
                    _ajax = null;
                    pthis = null;
                }
                else
                {
                    var locationurl = "", extramsg = "";
                    var ret;

                    if (e)
                    {
                        if (e.type == "timeout" || status == -408 || status == -504)
                        {
                            if (_ajax._httpretry >= 1)
                            {
                                ret = nexacro.__retryCommunication(_ajax, pthis);
                                if (ret !== false)
                                    return;
                            }

                            if (status == -408 || status == -504)
                                pthis.on_error(-1, "comm_fail_loaddetail", -status, locationurl, extramsg);
                            else
                                pthis.on_error(-1, "comm_fail_loaddetail", nexacro._CommunicationStatusTable.client_timeout, locationurl, extramsg);

                            _ajax._destroy();
                            _ajax = null;
                            pthis = null;
                        }
                        else if (e.type == "error")
                        {
                            // readystatchange가 발생(네트워크 끊겼을때)
                            //ajax.onerror bind 하여 0x2efd 처리.
                            if (_ajax._httpretry >= 1)
                            {
                                ret = nexacro.__retryCommunication(_ajax, pthis);
                                if (ret !== false)
                                    return;
                            }

                            pthis.on_error(-1, "comm_fail_loaddetail", nexacro._CommunicationStatusTable.failunknown, locationurl, extramsg);

                            _ajax.aborted = true;
                            ajax_handle.abort();
                            _ajax._destroy();
                            _ajax = null;
                            pthis = null;
                            //ajax_handle = null;
                            return;
                        }
                        else if (e.type == "load" || status == -404)
                        {
                            pthis.on_error(-1, "comm_fail_loaddetail", -status, locationurl, extramsg);
                            _ajax._destroy();
                            _ajax = null;
                            pthis = null;
                        }
                    }
                    else
                    {
                        pthis.on_error(-1, "comm_fail_loaddetail", -status, locationurl, extramsg);
                        _ajax._destroy();
                        _ajax = null;
                        pthis = null;
                    }
                }

            }
            //ajax_handle = null;
        };
    };

