    nexacro.__createHTMLEvent = function (doc, name)
    {
        if (doc.createEvent)
        {
            var evt = doc.createEvent('HTMLEvents');
            evt.initEvent(name, true, true);
            return evt;
        }

        return;
    };

    nexacro.__despatchEvent = function (node, evt)
    {
        if (node && evt)
            node.dispatchEvent(evt);
    };

